def count(b, n):
	l = []
	for i in range(n):
		c = 0
		for j in range(n):
			if b[j][j - i] == '1':
				c += 1
		l.append(c)
	return l
for i in range(int(input())):
	s = input()
	n = int(input())
	p = []
	for j in range(n):
		p.append(input())
	s = count(p, n)
	print(n - 2 * max(s) + sum(s))
